// Markdown and LaTeX rendering for Drops chat bubbles.
//
// The output is a small, safe subset of HTML for QML's Text.RichText. Every
// character from the model is escaped; only tags generated by this file are
// emitted. A browser is not involved, so raw HTML in a response is shown as
// text instead of being executed.
//
// This file is a plain QML JavaScript import. The final module export only
// exists so the Node-based renderer tests can load it directly.

function escapeHtml(value) {
    return String(value == null ? "" : value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

function normalizeOptions(options) {
    var value = options || {};
    return {
        link: value.link || "#7cc4e8",
        code: value.code || "#d8c9a3",
        muted: value.muted || "#92968a",
        border: value.border || "#4b5545"
    };
}

function stripTags(html) {
    return String(html == null ? "" : html)
        .replace(/<[^>]*>/g, "")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'")
        .replace(/&amp;/g, "&");
}

function expandTabs(value) {
    return String(value || "").replace(/\t/g, "    ");
}

function render(text, options) {
    var opt = normalizeOptions(options);
    var source = String(text == null ? "" : text)
        .replace(/\r\n?/g, "\n")
        .replace(/\u0000/g, "");
    if (!source.trim()) return "";

    var lines = source.split("\n");
    var out = [];
    var i = 0;
    while (i < lines.length) {
        var line = lines[i];
        if (!line.trim()) {
            i++;
            continue;
        }

        var fence = /^(\s*)(```+|~~~+)(.*)$/.exec(line);
        if (fence) {
            var marker = fence[2].charAt(0);
            var markerLength = fence[2].length;
            var close = new RegExp("^\\s*" + (marker === "`" ? "`" : "~") + "{" + markerLength + ",}\\s*$");
            var body = [];
            i++;
            while (i < lines.length) {
                if (close.test(lines[i])) {
                    i++;
                    break;
                }
                body.push(lines[i]);
                i++;
            }
            out.push(
                '<pre style="margin-top:0;margin-bottom:6px"><span style="font-family:monospace;color:' +
                opt.code + '">' + escapeHtml(body.join("\n")) + "</span></pre>"
            );
            continue;
        }

        var math = readDisplayMath(lines, i, opt);
        if (math) {
            out.push(math.html);
            i = math.next;
            continue;
        }

        var heading = /^\s{0,3}(#{1,6})\s+(.*?)\s*#*\s*$/.exec(line);
        if (heading) {
            out.push(renderHeading(heading[1].length, heading[2], opt));
            i++;
            continue;
        }

        if (i + 1 < lines.length && line.trim()) {
            if (/^\s*=+\s*$/.test(lines[i + 1])) {
                out.push(renderHeading(1, line.trim(), opt));
                i += 2;
                continue;
            }
            if (/^\s*-+\s*$/.test(lines[i + 1]) && !listMarker(line)) {
                out.push(renderHeading(2, line.trim(), opt));
                i += 2;
                continue;
            }
        }

        if (/^\s{0,3}(?:(?:\*\s*){3,}|(?:-\s*){3,}|(?:_\s*){3,})$/.test(line)) {
            out.push("<hr/>");
            i++;
            continue;
        }

        if (/^\s{0,3}>\s?/.test(line)) {
            var quoted = [];
            while (i < lines.length && /^\s{0,3}>\s?/.test(lines[i])) {
                quoted.push(lines[i].replace(/^\s{0,3}>\s?/, ""));
                i++;
            }
            out.push(
                '<blockquote style="margin-top:0;margin-bottom:6px;padding-left:8px;color:' +
                opt.muted + '">' + render(quoted.join("\n"), opt) + "</blockquote>"
            );
            continue;
        }

        if (listMarker(line)) {
            var list = parseList(lines, i, listIndent(line), opt);
            out.push(list.html);
            i = list.next;
            continue;
        }

        if (isTableStart(lines, i)) {
            var table = parseTable(lines, i, opt);
            out.push(table.html);
            i = table.next;
            continue;
        }

        var paragraph = [line];
        i++;
        while (i < lines.length && lines[i].trim() && !isBlockStart(lines, i)) {
            paragraph.push(lines[i]);
            i++;
        }
        out.push(
            '<p style="margin-top:0;margin-bottom:6px">' +
            renderInline(paragraph.join("\n"), opt) + "</p>"
        );
    }
    return out.join("");
}

function isBlockStart(lines, index) {
    var line = lines[index];
    if (!line.trim()) return true;
    if (/^\s*(```+|~~~+)/.test(line)) return true;
    if (/^\s{0,3}#{1,6}\s+/.test(line)) return true;
    if (/^\s{0,3}>\s?/.test(line)) return true;
    if (listMarker(line)) return true;
    if (/^\s{0,3}(?:(?:\*\s*){3,}|(?:-\s*){3,}|(?:_\s*){3,})$/.test(line)) return true;
    if (/^\s*\$\$\s*$/.test(line) || /^\s*\\\[\s*$/.test(line)) return true;
    if (/^\s*\$\$.+\$\$\s*$/.test(line)) return true;
    if (isTableStart(lines, index)) return true;
    return false;
}

function renderHeading(level, text, opt) {
    var inner = renderInline(text, opt);
    var size = level === 1 ? "+2" : level === 2 ? "+1" : "";
    var open = size ? '<font size="' + size + '">' : "";
    var close = size ? "</font>" : "";
    return '<p style="margin-top:0;margin-bottom:4px"><b>' + open + inner + close + "</b></p>";
}

function listIndent(line) {
    var match = /^(\s*)/.exec(line);
    return expandTabs(match ? match[1] : "").length;
}

function listMarker(line) {
    var match = /^(\s*)([-+*]|\d+[.)])\s+(.*)$/.exec(line);
    if (!match) return null;
    return {
        indent: expandTabs(match[1]).length,
        ordered: /^\d/.test(match[2]),
        start: parseInt(match[2], 10) || 1,
        text: match[3]
    };
}

function parseList(lines, index, indent, opt) {
    var first = listMarker(lines[index]);
    var ordered = first.ordered;
    var html = ordered
        ? '<ol start="' + first.start + '" style="margin-top:0;margin-bottom:6px;padding-left:18px">'
        : '<ul style="margin-top:0;margin-bottom:6px;padding-left:16px">';

    while (index < lines.length) {
        var marker = listMarker(lines[index]);
        if (!marker) {
            if (!lines[index].trim() && index + 1 < lines.length) {
                var peek = listMarker(lines[index + 1]);
                if (peek && peek.indent >= indent && peek.ordered === ordered) {
                    index++;
                    continue;
                }
            }
            break;
        }
        if (marker.indent < indent) break;
        if (marker.indent > indent) {
            var nested = parseList(lines, index, marker.indent, opt);
            html += nested.html;
            index = nested.next;
            continue;
        }
        if (marker.ordered !== ordered) break;

        var itemText = marker.text;
        index++;
        var task = /^\[([ xX])\]\s+(.*)$/.exec(itemText);
        var taskMark = "";
        if (task) {
            taskMark = task[1].toLowerCase() === "x"
                ? '<span style="color:' + opt.link + '">☑ </span>'
                : "☐ ";
            itemText = task[2];
        }
        var itemHtml = taskMark + renderInline(itemText, opt);

        while (index < lines.length) {
            var nestedMarker = listMarker(lines[index]);
            if (nestedMarker && nestedMarker.indent > indent) {
                var sub = parseList(lines, index, nestedMarker.indent, opt);
                itemHtml += sub.html;
                index = sub.next;
                continue;
            }
            if (!nestedMarker && lines[index].trim() && listIndent(lines[index]) > indent) {
                itemHtml += "<br/>" + renderInline(lines[index].trim(), opt);
                index++;
                continue;
            }
            break;
        }
        html += '<li style="margin-bottom:2px">' + itemHtml + "</li>";
    }
    html += ordered ? "</ol>" : "</ul>";
    return { html: html, next: index };
}

function isTableStart(lines, index) {
    if (lines[index].indexOf("|") < 0 || index + 1 >= lines.length) return false;
    return /^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(lines[index + 1]);
}

function splitTableRow(line) {
    var value = line.trim();
    if (value.charAt(0) === "|") value = value.substring(1);
    if (value.charAt(value.length - 1) === "|") value = value.substring(0, value.length - 1);
    return value.split("|").map(function (cell) { return cell.trim(); });
}

function parseTable(lines, index, opt) {
    var header = splitTableRow(lines[index]);
    var aligns = splitTableRow(lines[index + 1]).map(function (cell) {
        var left = cell.charAt(0) === ":";
        var right = cell.charAt(cell.length - 1) === ":";
        return left && right ? "center" : right ? "right" : left ? "left" : "";
    });
    index += 2;
    var rows = [];
    while (index < lines.length && lines[index].trim() && lines[index].indexOf("|") >= 0) {
        rows.push(splitTableRow(lines[index]));
        index++;
    }
    var html = '<table border="1" bordercolor="' + opt.border +
        '" cellspacing="0" cellpadding="2" width="100%" style="margin-top:0;margin-bottom:6px">';
    html += "<tr>";
    for (var c = 0; c < header.length; c++) {
        html += "<th" + (aligns[c] ? ' align="' + aligns[c] + '"' : "") + ">" +
            renderInline(header[c], opt) + "</th>";
    }
    html += "</tr>";
    for (var r = 0; r < rows.length; r++) {
        html += "<tr>";
        for (var cell = 0; cell < header.length; cell++) {
            html += "<td" + (aligns[cell] ? ' align="' + aligns[cell] + '"' : "") + ">" +
                renderInline(rows[r][cell] || "", opt) + "</td>";
        }
        html += "</tr>";
    }
    html += "</table>";
    return { html: html, next: index };
}

function readDisplayMath(lines, index, opt) {
    var line = lines[index];
    var match = /^\s*\$\$\s*$/.exec(line);
    if (match) {
        var body = [];
        var i = index + 1;
        while (i < lines.length && !/^\s*\$\$\s*$/.test(lines[i])) {
            body.push(lines[i]);
            i++;
        }
        if (i < lines.length) i++;
        return { html: displayMathHtml(body.join("\n"), opt), next: i };
    }
    match = /^\s*\$\$(.+?)\$\$\s*$/.exec(line);
    if (match) return { html: displayMathHtml(match[1], opt), next: index + 1 };

    match = /^\s*\\\[\s*$/.exec(line);
    if (match) {
        var body2 = [];
        var j = index + 1;
        while (j < lines.length && !/^\s*\\\]\s*$/.test(lines[j])) {
            body2.push(lines[j]);
            j++;
        }
        if (j < lines.length) j++;
        return { html: displayMathHtml(body2.join("\n"), opt), next: j };
    }
    match = /^\s*\\\[(.+?)\\\]\s*$/.exec(line);
    if (match) return { html: displayMathHtml(match[1], opt), next: index + 1 };
    return null;
}

function displayMathHtml(tex, opt) {
    return '<p align="center" style="margin-top:2px;margin-bottom:6px">' +
        renderMath(tex, true, opt) + "</p>";
}

function renderInline(text, options) {
    var opt = normalizeOptions(options);
    var tokens = [];
    var marker = "\u0001";

    function token(html) {
        tokens.push(html);
        return marker + (tokens.length - 1) + marker;
    }

    var value = String(text == null ? "" : text).replace(/\u0000/g, "");

    value = value.replace(/\\\n/g, function () { return token("<br/>"); });

    value = value.replace(/`([^`\n]+)`/g, function (_match, code) {
        return token('<span style="font-family:monospace;color:' + opt.code + '">' +
            escapeHtml(code) + "</span>");
    });

    value = value.replace(/\$\$([^\n]+?)\$\$/g, function (_match, tex) {
        return token(renderMath(tex, true, opt));
    });
    value = value.replace(/\\\(([\s\S]+?)\\\)/g, function (_match, tex) {
        return token(renderMath(tex, false, opt));
    });
    value = value.replace(/\$([^\s$\n](?:[^$\n]*[^\s$\n])?)\$/g, function (match, tex) {
        if (!looksLikeMath(tex)) return match;
        return token(renderMath(tex, false, opt));
    });

    value = value.replace(/\\([\\`*{}\[\]()#+\-.!_>~|$])/g, function (_match, ch) {
        return token(escapeHtml(ch));
    });

    value = value.replace(/!\[([^\]\n]*)\]\(((?:[^()\s]|\([^()\s]*\))+)\)/g, function (_match, alt, url) {
        return token(renderLink(alt || "image", url, opt));
    });
    value = value.replace(/\[([^\]\n]+)\]\(((?:[^()\s]|\([^()\s]*\))+)\)/g, function (_match, label, url) {
        return token(renderLink(label, url, opt));
    });
    value = value.replace(/<((?:https?:\/\/|mailto:)[^>\s]+)>/g, function (_match, url) {
        return token(renderLink(url, url, opt));
    });

    value = escapeHtml(value);

    value = value.replace(/\*\*\*([^*\n]+)\*\*\*/g, "<b><i>$1</i></b>");
    value = value.replace(/\*\*([^*\n]+)\*\*/g, "<b>$1</b>");
    value = value.replace(/__([^_\n]+)__/g, "<b>$1</b>");
    value = value.replace(/~~([^~\n]+)~~/g, "<s>$1</s>");
    value = value.replace(/(^|[^A-Za-z0-9])_([^_\n]+)_(?=$|[^A-Za-z0-9])/g, "$1<i>$2</i>");
    value = value.replace(/\*([^*\n]+)\*/g, "<i>$1</i>");

    value = value.replace(/[ \t]{2,}\n/g, "<br/>");
    value = value.replace(/\n/g, "<br/>");

    for (var pass = 0; pass < 3; pass++) {
        var before = value;
        value = value.replace(/\u0001(\d+)\u0001/g, function (_match, index) {
            return tokens[parseInt(index, 10)] || "";
        });
        if (value === before) break;
    }
    return value;
}

function looksLikeMath(tex) {
    if (/^[\d.,\s]+$/.test(tex)) return false;
    return /[A-Za-z\\^_{}=+\-*/<>≤≥≠≈∑∫√∂∞α-ωΑ-Ω]/.test(tex);
}

function safeUrl(url) {
    var value = String(url || "").trim();
    return /^(https?:\/\/|mailto:)/i.test(value) ? value : "";
}

function renderLink(label, url, opt) {
    var safe = safeUrl(url);
    var text = escapeHtml(label);
    if (!safe) return text;
    return '<a href="' + escapeHtml(safe) + '" style="color:' + opt.link + '">' + text + "</a>";
}

