var MATH_FUNCTIONS = {
    sin: 1, cos: 1, tan: 1, cot: 1, sec: 1, csc: 1, arcsin: 1, arccos: 1,
    arctan: 1, sinh: 1, cosh: 1, tanh: 1, log: 1, ln: 1, exp: 1, lim: 1,
    limsup: 1, liminf: 1, max: 1, min: 1, sup: 1, inf: 1, det: 1, gcd: 1,
    lcm: 1
};

function MathParser(source, display, options) {
    this.s = String(source == null ? "" : source);
    this.i = 0;
    this.display = !!display;
    this.opt = normalizeOptions(options);
}

MathParser.prototype.parse = function () {
    return this.parseSeq(null);
};

MathParser.prototype.skipSpaces = function () {
    while (this.i < this.s.length && /\s/.test(this.s.charAt(this.i))) this.i++;
};

MathParser.prototype.parseSeq = function (stop) {
    var out = "";
    var pendingSpace = false;
    while (this.i < this.s.length) {
        var ch = this.s.charAt(this.i);
        if (stop && ch === stop) break;
        if (ch === "}") break;
        if (/\s/.test(ch)) {
            this.i++;
            pendingSpace = out.length > 0;
            continue;
        }
        if (pendingSpace) {
            if (out && !/\s$/.test(out)) out += " ";
            pendingSpace = false;
        }
        if (ch === "{") {
            this.i++;
            var group = this.parseSeq("}");
            if (this.s.charAt(this.i) === "}") this.i++;
            out += group;
        } else if (ch === "\\") {
            out += this.parseCommand();
        } else if (ch === "^" || ch === "_") {
            this.i++;
            var atom = this.parseAtom();
            out += ch === "^" ? superscript(atom) : subscript(atom);
        } else if (ch === "&") {
            this.i++;
            out += " ";
        } else if (ch === "~") {
            this.i++;
            out += " ";
        } else if (ch === "'") {
            this.i++;
            out += "′";
        } else {
            out += escapeHtml(ch);
            this.i++;
        }
    }
    return out;
};

MathParser.prototype.parseAtom = function () {
    this.skipSpaces();
    if (this.i >= this.s.length) return "";
    var ch = this.s.charAt(this.i);
    if (ch === "{") {
        this.i++;
        var group = this.parseSeq("}");
        if (this.s.charAt(this.i) === "}") this.i++;
        return group;
    }
    if (ch === "\\") return this.parseCommand();
    this.i++;
    return escapeHtml(ch);
};

MathParser.prototype.parseGroup = function () {
    this.skipSpaces();
    if (this.s.charAt(this.i) === "{") {
        this.i++;
        var group = this.parseSeq("}");
        if (this.s.charAt(this.i) === "}") this.i++;
        return group;
    }
    return this.parseAtom();
};

MathParser.prototype.readRawGroup = function () {
    this.skipSpaces();
    if (this.s.charAt(this.i) !== "{") return stripTags(this.parseAtom());
    this.i++;
    var depth = 1;
    var start = this.i;
    while (this.i < this.s.length) {
        var ch = this.s.charAt(this.i);
        if (ch === "\\") {
            this.i += 2;
            continue;
        }
        if (ch === "{") depth++;
        else if (ch === "}") {
            depth--;
            if (depth === 0) {
                var raw = this.s.slice(start, this.i);
                this.i++;
                return raw;
            }
        }
        this.i++;
    }
    return this.s.slice(start);
};

MathParser.prototype.readOptionalBracket = function () {
    this.skipSpaces();
    if (this.s.charAt(this.i) !== "[") return null;
    this.i++;
    var start = this.i;
    while (this.i < this.s.length && this.s.charAt(this.i) !== "]") this.i++;
    var raw = this.s.slice(start, this.i);
    if (this.s.charAt(this.i) === "]") this.i++;
    return raw;
};

MathParser.prototype.parseCommand = function () {
    this.i++;
    if (this.i >= this.s.length) return "\\";
    var ch = this.s.charAt(this.i);
    if (/[A-Za-z]/.test(ch)) {
        var start = this.i;
        while (this.i < this.s.length && /[A-Za-z]/.test(this.s.charAt(this.i))) this.i++;
        var name = this.s.slice(start, this.i);
        if (this.s.charAt(this.i) === "*") this.i++;
        return this.command(name);
    }
    this.i++;
    if (ch === "\\") return this.display ? "<br/>" : "; ";
    if (ch === "{" || ch === "}" || ch === "$" || ch === "%" || ch === "&" ||
        ch === "#" || ch === "_") return escapeHtml(ch);
    if (ch === "," || ch === ";" || ch === ":" || ch === "!" || ch === " ") return " ";
    if (ch === "|") return "‖";
    return escapeHtml(ch);
};

MathParser.prototype.command = function (name) {
    if (Object.prototype.hasOwnProperty.call(MATH_SYMBOLS, name)) return MATH_SYMBOLS[name];
    if (MATH_FUNCTIONS[name]) return name;

    switch (name) {
        case "frac":
            return fractionHtml(this.parseGroup(), this.parseGroup());
        case "dfrac":
        case "tfrac":
            return fractionHtml(this.parseGroup(), this.parseGroup());
        case "binom":
            return "C(" + stripTags(this.parseGroup()) + ", " + stripTags(this.parseGroup()) + ")";
        case "sqrt": {
            var index = this.readOptionalBracket();
            var radicand = this.parseGroup();
            if (!index) return "√(" + radicand + ")";
            if (index.trim() === "3") return "∛(" + radicand + ")";
            return "<sup>" + renderMath(index, false, this.opt) + "</sup>√(" + radicand + ")";
        }
        case "cbrt":
            return "∛(" + this.parseGroup() + ")";
        case "text":
        case "mbox":
        case "textnormal":
        case "textrm":
            return escapeHtml(latexText(this.readRawGroup()));
        case "operatorname":
            return escapeHtml(latexText(this.readRawGroup()));
        case "mathrm":
        case "mathsf":
        case "mathtt": {
            var raw = latexText(this.readRawGroup());
            if (name === "mathtt") return '<span style="font-family:monospace">' + escapeHtml(raw) + "</span>";
            return escapeHtml(raw);
        }
        case "mathbf":
            return "<b>" + this.parseGroup() + "</b>";
        case "mathit":
        case "textit":
            return "<i>" + this.parseGroup() + "</i>";
        case "mathbb":
            return mapLetters(this.parseGroup(), BLACKBOARD);
        case "mathcal":
        case "mathscr":
            return mapLetters(this.parseGroup(), CALLIGRAPHIC);
        case "mathfrak":
            return this.parseGroup();
        case "overline":
            return '<span style="text-decoration:overline">' + this.parseGroup() + "</span>";
        case "underline":
            return "<u>" + this.parseGroup() + "</u>";
        case "hat":
            return this.parseGroup() + "\u0302";
        case "widehat":
            return this.parseGroup() + "\u0302";
        case "tilde":
            return this.parseGroup() + "\u0303";
        case "widetilde":
            return this.parseGroup() + "\u0303";
        case "vec":
            return this.parseGroup() + "\u20d7";
        case "dot":
            return this.parseGroup() + "\u0307";
        case "ddot":
            return this.parseGroup() + "\u0308";
        case "bar":
            return this.parseGroup() + "\u0304";
        case "not": {
            var negated = this.parseAtom();
            var plain = stripTags(negated);
            return plain ? plain + "\u0338" : negated;
        }
        case "left":
        case "right":
        case "middle":
        case "big":
        case "Big":
        case "bigg":
        case "Bigg":
        case "bigl":
        case "bigr":
        case "Bigl":
        case "Bigr":
        case "biggl":
        case "biggr":
            return this.readDelimiter();
        case "begin": {
            var env = this.readRawGroup().trim();
            var endMarker = "\\end{" + env + "}";
            var end = this.s.indexOf(endMarker, this.i);
            if (end < 0) return "";
            var body = this.s.slice(this.i, end);
            this.i = end + endMarker.length;
            if (env === "array") {
                body = body.replace(/^\s*\{[^}]*\}/, "");
                env = "matrix";
            }
            return this.renderEnvironment(env, body);
        }
        case "end":
            return "";
        case "pmod":
            return "(mod " + this.parseGroup() + ")";
        case "mod":
        case "bmod":
            return "mod";
        case "overbrace":
            return this.parseGroup() + "\u23de";
        case "underbrace":
            return this.parseGroup() + "\u23df";
        case "overset":
        case "stackrel": {
            var over = this.parseGroup();
            var base = this.parseGroup();
            return base + "<sup>" + over + "</sup>";
        }
        case "underset": {
            var under = this.parseGroup();
            var baseUnder = this.parseGroup();
            return baseUnder + "<sub>" + under + "</sub>";
        }
        case "boxed":
        case "fbox":
            return "[" + this.parseGroup() + "]";
        case "cancel":
        case "bcancel":
        case "xcancel":
            return '<span style="text-decoration:line-through">' + this.parseGroup() + "</span>";
        case "color":
        case "textcolor":
            this.readRawGroup();
            return this.parseGroup();
        case "label":
            this.readRawGroup();
            return "";
        case "ref":
        case "eqref":
            return "(" + escapeHtml(latexText(this.readRawGroup())) + ")";
        case "tag":
            return '<span style="color:' + this.opt.muted + '">(' +
                escapeHtml(latexText(this.readRawGroup())) + ")</span>";
        case "phantom":
        case "hphantom":
        case "vphantom":
            this.readRawGroup();
            return " ";
        case "hspace":
        case "vspace":
            this.readRawGroup();
            return " ";
        case "displaystyle":
        case "textstyle":
        case "scriptstyle":
        case "scriptscriptstyle":
        case "limits":
        case "nolimits":
        case "mathstrut":
        case "strut":
            return "";
        case "quad":
            return "  ";
        case "qquad":
            return "    ";
        case "enspace":
        case "thinspace":
        case "medspace":
        case "thickspace":
            return " ";
        case "negthinspace":
            return "";
        case "mathop":
        case "mathbin":
        case "mathrel":
        case "mathord":
        case "mathopen":
        case "mathclose":
        case "mathpunct":
        case "substack":
        case "raisebox":
            return this.parseGroup();
        case "LaTeX":
        case "TeX":
            return name;
        default:
            return escapeHtml("\\" + name);
    }
};

MathParser.prototype.readDelimiter = function () {
    this.skipSpaces();
    if (this.i >= this.s.length) return "";
    var ch = this.s.charAt(this.i);
    if (ch === "\\") {
        var start = this.i + 1;
        var j = start;
        while (j < this.s.length && /[A-Za-z]/.test(this.s.charAt(j))) j++;
        if (j === start) {
            this.i += 2;
            return escapeHtml(this.s.charAt(start));
        }
        var name = this.s.slice(start, j);
        this.i = j;
        if (Object.prototype.hasOwnProperty.call(MATH_SYMBOLS, name)) return MATH_SYMBOLS[name];
        return "";
    }
    this.i++;
    if (ch === ".") return "";
    return escapeHtml(ch);
};

MathParser.prototype.renderEnvironment = function (env, body) {
    var rows = String(body).split("\\\\");
    var rendered = [];
    for (var r = 0; r < rows.length; r++) {
        var cells = rows[r].split("&");
        var parts = [];
        for (var c = 0; c < cells.length; c++) {
            parts.push(new MathParser(cells[c], this.display, this.opt).parse());
        }
        rendered.push(parts.join("  "));
    }
    var separator = this.display ? "<br/>" : "; ";
    var text = rendered.join(separator);
    switch (env) {
        case "pmatrix": return "(" + text + ")";
        case "bmatrix": return "[" + text + "]";
        case "Bmatrix": return "{" + text + "}";
        case "vmatrix": return "|" + text + "|";
        case "Vmatrix": return "‖" + text + "‖";
        case "cases": return "{ " + rendered.join("; ") + " }";
        case "aligned":
        case "align":
        case "align*":
        case "gathered":
            return rendered.join("<br/>");
        default:
            return text;
    }
};

function latexText(raw) {
    return String(raw == null ? "" : raw)
        .replace(/\\textbackslash/g, "\\")
        .replace(/\\([{}%$&#_])/g, "$1")
        .replace(/\\ /g, " ")
        .replace(/~/g, " ");
}

function fractionHtml(numerator, denominator) {
    function wrap(value) {
        var plain = stripTags(value).trim();
        if (!plain) return value;
        return /[+\-−=<>≤≥ ,;]/.test(plain) || plain.length > 1 ? "(" + value + ")" : value;
    }
    return wrap(numerator) + "/" + wrap(denominator);
}

var SUPERSCRIPTS = {
    "0": "⁰", "1": "¹", "2": "²", "3": "³", "4": "⁴", "5": "⁵", "6": "⁶",
    "7": "⁷", "8": "⁸", "9": "⁹", "+": "⁺", "-": "⁻", "=": "⁼", "(": "⁽",
    ")": "⁾", "n": "ⁿ", "i": "ⁱ"
};

var SUBSCRIPTS = {
    "0": "₀", "1": "₁", "2": "₂", "3": "₃", "4": "₄", "5": "₅", "6": "₆",
    "7": "₇", "8": "₈", "9": "₉", "+": "₊", "-": "₋", "=": "₌", "(": "₍",
    ")": "₎", "a": "ₐ", "e": "ₑ", "o": "ₒ", "x": "ₓ", "h": "ₕ", "k": "ₖ",
    "l": "ₗ", "m": "ₘ", "n": "ₙ", "p": "ₚ", "s": "ₛ", "t": "ₜ", "i": "ᵢ",
    "j": "ⱼ", "r": "ᵣ", "u": "ᵤ", "v": "ᵥ"
};

function mapScript(html, table, tag) {
    var plain = stripTags(html);
    if (!plain) return html;
    var out = "";
    for (var i = 0; i < plain.length; i++) {
        var ch = plain.charAt(i);
        if (!Object.prototype.hasOwnProperty.call(table, ch)) return "<" + tag + ">" + html + "</" + tag + ">";
        out += table[ch];
    }
    return out;
}

function superscript(html) {
    return mapScript(html, SUPERSCRIPTS, "sup");
}

function subscript(html) {
    return mapScript(html, SUBSCRIPTS, "sub");
}

var BLACKBOARD = {};
var CALLIGRAPHIC = {};
function toChars(value) {
    var out = [];
    for (var i = 0; i < value.length; i++) {
        var code = value.charCodeAt(i);
        if (code >= 0xD800 && code <= 0xDBFF && i + 1 < value.length) {
            out.push(value.charAt(i) + value.charAt(i + 1));
            i++;
        } else {
            out.push(value.charAt(i));
        }
    }
    return out;
}
(function () {
    var upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    var lower = "abcdefghijklmnopqrstuvwxyz";
    var blackUpper = toChars("𝔸𝔹ℂ𝔻𝔼𝔽𝔾ℍ𝕀𝕁𝕂𝕃𝕄ℕ𝕆ℙℚℝ𝕊𝕋𝕌𝕍𝕎𝕏𝕐ℤ");
    var blackLower = toChars("𝕒𝕓𝕔𝕕𝕖𝕗𝕘𝕙𝕚𝕛𝕜𝕝𝕞𝕟𝕠𝕡𝕢𝕣𝕤𝕥𝕦𝕧𝕨𝕩𝕪𝕫");
    var blackDigits = toChars("𝟘𝟙𝟚𝟛𝟜𝟝𝟞𝟟𝟠𝟡");
    var scriptUpper = toChars("𝒜ℬ𝒞𝒟ℰℱ𝒢ℋℐ𝒥𝒦ℒℳ𝒩𝒪𝒫𝒬ℛ𝒮𝒯𝒰𝒱𝒲𝒳𝒴𝒵");
    var scriptLower = toChars("𝒶𝒷𝒸𝒹ℯ𝒻ℊ𝒽𝒾𝒿𝓀𝓁𝓂𝓃ℴ𝓅𝓆𝓇𝓈𝓉𝓊𝓋𝓌𝓍𝓎𝓏");
    for (var i = 0; i < 26; i++) {
        BLACKBOARD[upper.charAt(i)] = blackUpper[i];
        BLACKBOARD[lower.charAt(i)] = blackLower[i];
        CALLIGRAPHIC[upper.charAt(i)] = scriptUpper[i];
        CALLIGRAPHIC[lower.charAt(i)] = scriptLower[i];
    }
    for (var d = 0; d < 10; d++) BLACKBOARD[String(d)] = blackDigits[d];
})();

function mapLetters(html, table) {
    var plain = stripTags(html);
    if (!plain) return html;
    var out = "";
    for (var i = 0; i < plain.length; i++) {
        var ch = plain.charAt(i);
        if (Object.prototype.hasOwnProperty.call(table, ch)) out += table[ch];
        else if (/[A-Za-z0-9]/.test(ch)) return html;
        else out += escapeHtml(ch);
    }
    return out;
}

function renderMath(tex, display, options) {
    var opt = normalizeOptions(options);
    var source = String(tex == null ? "" : tex).replace(/\r\n?/g, "\n");
    return new MathParser(source, !!display, opt).parse();
}

if (typeof module !== "undefined" && module.exports) {
    module.exports = {
        render: render,
        renderInline: renderInline,
        renderMath: renderMath,
        escapeHtml: escapeHtml
    };
}
